module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    parameter IDLE = 3'b000;
    parameter STAGE1 = 3'b001;
    parameter STAGE2 = 3'b010;
    parameter STAGE3 = 3'b011;
    parameter STAGE4 = 3'b100;

    reg [2:0] current_state;
    reg [2:0] next_state;
    reg enable_reg;
    reg [63:0] adda_reg;
    reg [63:0] addb_reg;
    reg [64:0] sum_stage1;
    reg [64:0] carry_stage1;
    reg [64:0] sum_stage2;
    reg [64:0] carry_stage2;
    reg [64:0] sum_stage3;
    reg [64:0] carry_stage3;
    reg [64:0] sum_stage4;
    reg [64:0] carry_stage4;
    reg [64:0] final_sum;
    reg [64:0] final_carry;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            enable_reg <= 0;
            adda_reg <= 64'd0;
            addb_reg <= 64'd0;
            sum_stage1 <= 65'd0;
            carry_stage1 <= 65'd0;
            sum_stage2 <= 65'd0;
            carry_stage2 <= 65'd0;
            sum_stage3 <= 65'd0;
            carry_stage3 <= 65'd0;
            sum_stage4 <= 65'd0;
            carry_stage4 <= 65'd0;
            final_sum <= 65'd0;
            final_carry <= 65'd0;
        end else begin
            current_state <= next_state;
            enable_reg <= (current_state == STAGE4);
            adda_reg <= adda;
            addb_reg <= addb;
            sum_stage1 <= adda_reg + addb_reg;
            carry_stage1 <= {sum_stage1[64], sum_stage1[63:0]};
            sum_stage2 <= sum_stage1 + carry_stage1;
            carry_stage2 <= {sum_stage2[64], sum_stage2[63:0]};
            sum_stage3 <= sum_stage2 + carry_stage2;
            carry_stage3 <= {sum_stage3[64], sum_stage3[63:0]};
            sum_stage4 <= sum_stage3 + carry_stage3;
            carry_stage4 <= {sum_stage4[64], sum_stage4[63:0]};
            final_sum <= sum_stage4;
            final_carry <= carry_stage4;
        end
    end

    assign result = final_sum;
    assign o_en = enable_reg;

endmodule
